import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import { fileURLToPath } from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));
const context = { window: {} };
for (const file of ['content.js', 'catalog.js']) {
  vm.runInNewContext(fs.readFileSync(path.join(root, 'assets', file), 'utf8'), context, { filename: file });
}
const content = context.window.AIO_CONTENT;
const release = context.window.AIO_RELEASE;
if (!content?.tour.length || !release?.templates.length) throw new Error('The report content and download catalog are required.');
const e = value => String(value ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const slug = value => value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const plain = html => html.replace(/<[^>]*>/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&middot;/g, ' ').replace(/\s+/g, ' ').trim();
const teamEmail = 'mailto:copilot-roi-advisory-team-gh@microsoft.com';
const team = `<a href="${teamEmail}">Microsoft Copilot Analytics team</a>`;
const referenceLinks = {
  'mini-kitchen': 'https://aka.ms/Mini-Kitchen',
  'pax cookbook mini-kitchen': 'https://aka.ms/Mini-Kitchen',
  'power bi desktop': 'https://aka.ms/powerbidesktop',
  'powershell 7': 'https://aka.ms/PowerShell',
  'powershell 7 or later': 'https://aka.ms/PowerShell',
  'python 3.10': 'https://www.python.org/downloads/',
  'python 3.10 or later': 'https://www.python.org/downloads/',
  'microsoft copilot analytics team': teamEmail
};
function linkReferences(html) {
  const excluded = new Set(['a', 'pre', 'code', 'summary', 'button', 'script', 'style']);
  const depth = new Map();
  return html.split(/(<[^>]+>)/g).map(part => {
    if (part.startsWith('<')) {
      const tag = part.match(/^<(\/?)([a-z][a-z0-9]*)\b/i);
      if (tag && excluded.has(tag[2].toLowerCase())) {
        const name = tag[2].toLowerCase();
        depth.set(name, Math.max(0, (depth.get(name) || 0) + (tag[1] ? -1 : 1)));
      }
      return part;
    }
    if ([...depth.values()].some(value => value > 0)) return part;
    return part.replace(/\b(?:PAX Cookbook Mini-Kitchen|Mini-Kitchen|Power BI Desktop|PowerShell 7(?: or later)?|Python 3\.10(?: or later)?|Microsoft Copilot Analytics team)\b/gi, label => {
      const href = referenceLinks[label.toLowerCase()];
      return `<a href="${href}"${href.startsWith('mailto:') ? '' : ' target="_blank" rel="noopener noreferrer"'}>${label}</a>`;
    });
  }).join('');
}
