function setup() {
  const templateRows = release.templates.map(t => `<tr><th scope="row"><a href="#${t.id}">${e(t.title)}</a></th><td>${e(t.bestFor)}</td><td>${t.status === 'available' ? `<a href="${e(t.href)}">Download template ${icon('download')}</a>` : 'Download coming soon'}</td></tr>`).join('');
  return pageHead('Get started', 'From your data.<br><span class="gradient-text">To your first useful view.</span>', 'Four practical steps: prepare, collect, open and share. Your IT team can help with permissions; Mini-Kitchen helps with PAX.') + `
  <section class="container quick-start" ${searchAttr('sample', 'Try fictional sample data')}><span class="icon-tile purple">${icon('play')}</span><div><h2>Just exploring? Start with the sample.</h2><p>Install ${external('Power BI Desktop', 'https://aka.ms/powerbidesktop')}, download the Local CSV template and the three sample files, then extract the activity CSV from its ZIP. Open the template and paste the full paths to those CSVs. No tenant access or PAX collection is needed.</p><div class="button-row">${button('Get the sample files', 'downloads.html#sample-data', 'secondary', 'download')}<a class="text-link" href="#open-template">See where the paths go ${icon('arrow')}</a></div></div></section>
  <nav class="container jump-nav" aria-label="Setup steps"><a href="#prepare">1. Prepare</a><a href="#collect">2. Collect</a><a href="#open-template">3. Open</a><a href="#share">4. Share</a>${watchButton('#setup-video')}</nav>
  <section class="section container setup-guide" ${searchAttr('prepare', 'Step 1: Prepare and choose your connection')}><div class="guide-step-label"><span>01</span><p>Prepare</p></div><div class="guide-step-body"><h2>Choose where your data will live.</h2><p>All editions share the same report experience. Choose the connection that fits your team.</p><div class="table-wrap edition-table"><table><thead><tr><th>Connection</th><th>When it fits</th><th>Template</th></tr></thead><tbody>${templateRows}</tbody></table></div><h3>Before you collect your organization's data</h3><ul class="check-list"><li>Install current Power BI Desktop. PAX also uses PowerShell 7 or later and Python 3.10 or later; Mini-Kitchen explains the tools.</li><li>Ask IT to confirm audit logging is enabled, the history you need is available and the collection account has the right permissions.</li><li>Agree on who may see the report and whether individual activity is appropriate under your privacy and employee-reporting policies.</li><li>Confirm Power BI sharing licenses or capacity. Fabric OneLake routes also need suitable Fabric capacity and Lakehouse access.</li></ul>${note('You do not need to be the administrator.', 'Your IT team can help with collection permissions, storage and report sharing. <a href="setup-reference.html#administrator">Use the administrator checklist</a>. Newly enabled audit logging does not recover the past; records can take up to 24 hours to appear.')}</div></section>
  <section class="section section-tinted" ${searchAttr('collect', 'Step 2: Collect with PAX Mini-Kitchen or Fabric OneLake notebooks')}><div class="container setup-guide"><div class="guide-step-label"><span>02</span><p>Collect</p></div><div class="guide-step-body"><h2>Prepare the report's data.</h2><p>Already have matching, dashboard-ready inputs from your data team? You can go straight to <a href="#open-template">opening the template</a>. Raw Purview exports are not ready-to-use report inputs.</p>${kitchenPanel()}<p class="guide-intro">Follow the route you chose. Fabric OneLake PAX and Fabric OneLake notebooks use different tables; do not mix the two.</p>
  <details class="route-detail" name="collection-edition" id="fabric"><summary>${icon('layers')}Fabric OneLake: notebooks</summary><div><p>Use this route if your team wants collection and preparation inside Fabric OneLake rather than PAX.</p><ol><li>Import the audit, organization, licensing and preparation notebooks. Attach the same default Lakehouse to all four.</li><li>Have IT configure the collection application's permissions and Key Vault secret access. Never put secrets in notebook cells.</li><li>Run the three collectors, then the report preparation notebook. A pipeline can coordinate these steps.</li><li>Wait for the prepared tables and their matching <strong>Ready</strong> status to appear in the SQL analytics endpoint. SQL can lag behind the Lakehouse update.</li></ol><div class="button-row">${button('Get Fabric OneLake notebooks', 'downloads.html#fabric-onelake-notebooks', 'secondary', 'download')}<a class="text-link" href="setup-reference.html#fabric-notebooks">Detailed Fabric OneLake setup ${icon('arrow')}</a></div></div></details>
  <details class="route-detail" name="collection-edition" id="pax-fabric"><summary>${icon('layers')}Fabric OneLake: PAX</summary><div><p>Use Mini-Kitchen to configure PAX for AI-in-One and Fabric OneLake output. This route reads the processed <code>AIO_Users</code> and <code>AIO_CopilotInteractions</code> tables, with an optional <code>Agent365</code> catalog. It does not use the notebook edition's preparation tables.</p><p>Let the whole PAX update finish, then wait for SQL synchronization. Do not update tables while Power BI is refreshing them.</p>${note('Template download coming soon.', 'The Fabric OneLake PAX template is not yet available to download. Do not substitute the Fabric OneLake notebook template.')}<a class="text-link" href="setup-reference.html#fabric-pax">Detailed Fabric OneLake PAX setup ${icon('arrow')}</a></div></details>
  <details class="route-detail" name="collection-edition" id="sharepoint"><summary>${icon('book')}SharePoint</summary><div><ol><li>In Mini-Kitchen, choose <strong>AI-in-One</strong> and your SharePoint destination. It helps with both your first collection and later updates.</li><li>Download PAX from Mini-Kitchen and run the command it creates in your environment.</li><li>Keep the matching Interactions and Users CSVs together. Collecting the Agent 365 catalog is recommended but optional.</li><li>For each CSV, select it in SharePoint, open <strong>Details</strong> and copy <strong>Path</strong>. Do not use a sharing link or the browser address bar.</li></ol><p>For app-only SharePoint collection, an administrator must grant access to the intended site; consent to <code>Sites.Selected</code> alone does not grant that access.</p><a class="text-link" href="setup-reference.html#sharepoint-setup">Detailed SharePoint setup ${icon('arrow')}</a></div></details>
  <details class="route-detail" name="collection-edition" id="local"><summary>${icon('chart')}Local CSV</summary><div><ol><li>In Mini-Kitchen, choose <strong>AI-in-One</strong> and a local output folder. Use it for your first collection and later updates.</li><li>Download PAX there and run the command it creates. Keep the resulting matching CSV files together.</li><li>In File Explorer, use <strong>Copy as path</strong>. Remove the surrounding quotation marks before pasting into Power BI.</li></ol><p>Desktop can read the files directly. Scheduled Power BI Service refresh requires a gateway that can read the same paths.</p><a class="text-link" href="setup-reference.html#local-setup">Detailed Local CSV setup ${icon('arrow')}</a></div></details>
  </div></div></section>
  <section class="section container setup-guide" ${searchAttr('open-template', 'Step 3: Open the template and enter parameters')}><div class="guide-step-label"><span>03</span><p>Open</p></div><div class="guide-step-body"><h2>Open your template in Power BI Desktop.</h2><ol class="plain-steps"><li><a href="downloads.html#templates">Download the template</a> that matches your connection. Open the <code>.pbit</code> file in Desktop, not Excel or the browser.</li><li>Enter the requested source details using the matching CSV files or Fabric OneLake connection below.</li><li>Keep <strong>Minimum Group Size at 3</strong> for team-level reporting. ${policy}</li><li>Select <strong>Load</strong> and sign in to the source if prompted. Start on Copilot Usage Explorer and check your teams and dates.</li></ol><div class="parameter-reference">${release.templates.map(t => `<details class="route-detail" name="template-parameters"><summary>Parameters for ${e(t.title)}</summary><div><dl class="parameter-list">${t.parameters.map(p => `<dt>${e(p.name)}</dt><dd>${e(p.value)}</dd>`).join('')}</dl>${t.id === 'local' ? '<p>For the sample: Interactions uses the extracted activity CSV; Org Data File uses the sample people CSV; Agent 365 uses the sample agent CSV.</p>' : ''}${t.id === 'fabric' || t.id === 'pax-fabric' ? '<p>Use the <strong>SQL analytics endpoint hostname</strong> and database name, not a OneLake file URL. Both Fabric OneLake editions use SQL Import, not Direct Lake.</p>' : ''}</div></details>`).join('')}</div>${note('Changing the group-size setting later?', 'In Desktop, select Home &gt; Transform data &gt; Manage parameters &gt; Minimum Group Size. Change the existing parameter, apply changes and clear old filters. Do not create a new modeling parameter.')}</div></section>
  <section class="section section-tinted" ${searchAttr('share', 'Step 4: Secure, publish and schedule refresh')}><div class="container setup-guide"><div class="guide-step-label"><span>04</span><p>Share</p></div><div class="guide-step-body"><h2>Set access before you share.</h2><p>Just trying the sample? You can keep it in Desktop. For a shared report, your report owner follows these steps.</p><ol class="plain-steps"><li>Publish to the intended Power BI workspace.</li><li>Open the semantic model's <strong>Security</strong> settings. Add people or security groups to the appropriate named role: <strong>Reporting hierarchy</strong> for their own reporting organization, or <strong>All data viewers</strong> for full-dataset access when your policies permit it.</li><li>Save and test representative viewer accounts. Share through an app or Viewer access. Workspace Admins, Members and Contributors are not restricted like Viewers.</li><li>Configure source credentials and try <strong>Refresh now</strong>. Schedule later refreshes only after data collection and preparation finish.</li></ol><div class="refresh-flow" aria-label="Refresh order"><span>Collect or update data</span>${icon('arrow')}<span>Finish preparation and synchronization</span>${icon('arrow')}<span>Refresh Power BI</span></div><details class="route-detail" id="keep-current"><summary>How do I keep the data current?</summary><div><p><strong>PAX collection:</strong> use Mini-Kitchen for <strong>both the first collection and later updates</strong>. The first collection gets the history you choose. Later commands add new days to the same report files or Fabric OneLake tables, so you do not have to reconnect the report each time.</p><p><strong>Make it automatic:</strong> ask IT to schedule those updates and keep the Power BI refresh after they finish. Mini-Kitchen creates the commands; it does not run or schedule them for you. The <a href="setup-reference.html#recurring">ongoing collection guide</a> explains the details for whoever sets up the schedule.</p><p><strong>SharePoint:</strong> the report's refresh account needs read access to the files. Leave enough time after collection for the update to finish.</p><p><strong>Local CSV:</strong> scheduled refresh needs a gateway that can read the files. Otherwise, refresh in Desktop and republish.</p><p><strong>Fabric OneLake:</strong> finish PAX or notebook collection and preparation, then wait for the SQL connection to show the completed data. Do not update tables while Power BI refreshes them.</p></div></details><div class="button-row">${button('Understand privacy and access', 'learn.html#privacy', 'secondary', 'shield')}${button('Get help with setup', 'help.html', 'secondary')}</div></div></div></section>
  <section class="section container" ${searchAttr('setup-video', 'AI-in-One setup video')}><div class="two-columns align-center"><div>${eyebrow('Watch the steps')}<h2>See the setup in action.</h2><p class="lead">Pause, follow along and return to the guide whenever you need it.</p></div><div>${setupVideo()}</div></div></section>`;
}

function tourPanel(p) {
  return `<div class="tour-heading">${eyebrow(p.area)}<h2>${e(p.title)}</h2><p class="question-line">${e(p.question)}</p></div>${p.image ? `<button class="screenshot-button" data-zoom="${e(p.image)}" data-title="${e(p.title)}" aria-label="Enlarge ${e(p.title)} screenshot"><img src="${e(p.image)}" alt="${e(p.title)}, fictional example data" width="1280" height="792"><span>${icon('search')}Enlarge screenshot</span></button><p class="image-caption">Fictional example data. Screenshots show individual detail; templates default to team-level reporting with Minimum Group Size 3.</p>` : `<div class="glossary-preview">${icon('book')}<h3>A definition, right when you need it.</h3><p>The in-report Metric Glossary &amp; Guide filters definitions by page.</p>${button('Browse the web glossary', 'learn.html#glossary', 'secondary')}</div>`}<p class="tour-summary">${e(p.summary)}</p><div class="tour-notes"><article><h3>What to look for</h3><ul>${p.bullets.map(b => `<li>${e(b)}</li>`).join('')}</ul></article><article class="tip-card"><p class="eyebrow">TRY THIS</p><p>${e(p.tip)}</p></article></div>${p.caution ? note('Read it in context', e(p.caution)) : ''}<div class="tour-controls"><button class="button button-secondary" data-tour-prev ${p.number === 1 ? 'disabled' : ''}>Previous view</button><span>${p.number} / ${content.tour.length}</span><button class="button button-primary" data-tour-next ${p.number === content.tour.length ? 'disabled' : ''}>Next view ${icon('arrow')}</button></div>`;
}
function explore() {
  return pageHead('Explore the dashboard', 'Better questions.<br><span class="gradient-text">Clearer conversations.</span>', 'Find the view that helps you understand adoption, habits or agent engagement. Explore real report screenshots with fictional data.') + `
  <section class="container tour-layout" ${searchAttr('report-tour', 'Explore report views')}><aside class="tour-rail"><label class="search-field">${icon('search')}<input id="tour-search" type="search" placeholder="Find a view or question" aria-label="Find a report view"></label><nav aria-label="Report views" id="tour-nav">${content.tour.map(p => `<a href="#${e(p.id)}" data-tour="${e(p.id)}">${e(p.title)}</a>`).join('')}</nav><p class="empty-state" id="tour-empty" hidden>No matching view. Try "agents", "habit" or "license".</p></aside><div id="tour-detail" class="tour-detail" aria-live="polite">${tourPanel(content.tour[0])}</div></section>
  ${content.tour.map(p => `<template id="tour-template-${e(p.id)}">${tourPanel(p)}</template>`).join('')}
  <noscript><section class="section container"><h2>Complete report tour</h2>${content.tour.map(p => `<article class="section" id="${e(p.id)}"><h2>${e(p.title)}</h2><p>${e(p.question)}</p>${p.image ? `<img src="${e(p.image)}" alt="${e(p.title)}, fictional data" loading="lazy" width="1280" height="792">` : ''}<p>${e(p.summary)}</p><ul>${p.bullets.map(b => `<li>${e(b)}</li>`).join('')}</ul><p><strong>Try this:</strong> ${e(p.tip)}</p><p><strong>Context:</strong> ${e(p.caution)}</p></article>`).join('')}</section></noscript>
  <section class="section container" ${searchAttr('report-video', 'Watch the report overview')}><div class="section-heading"><h2>See the report in motion.</h2><p>A captioned introduction to the experience, alongside the detailed screenshot tour above.</p></div>${overviewVideo()}</section>
  <section class="section container"><div class="soft-cta"><div><h2>Ready to try it yourself?</h2><p>The fictional sample needs Power BI Desktop, not tenant collection permissions.</p></div>${button('Try sample data', 'get-started.html#sample')}</div></section>`;
}

function historyIllustration() {
  return `<figure class="license-story" aria-labelledby="history-caption"><div class="story-person">${icon('people')}<strong>One person, recorded over time</strong><span>Illustrative example</span></div><div class="observation-row"><div class="observation free"><span>Monday's collection</span><strong>Recorded as unlicensed</strong><p>Collection showed no Microsoft 365 Copilot license.</p></div><div class="observation paid"><span>Friday's collection</span><strong>Recorded as licensed</strong><p>Collection showed a Microsoft 365 Copilot license.</p></div></div><div class="observation-gap"><span></span><p>A change happened somewhere in between.<br><strong>The exact assignment time is not known.</strong></p><span></span></div><div class="history-outcomes"><div>${icon('people')}<strong>1 person</strong><span>in the overall total</span></div><div>${icon('layers')}<strong>Both license groups</strong><span>can include this person in the same period</span></div></div><figcaption id="history-caption">Collection records observations, not a complete license-assignment log. Without history, the report uses the supplied snapshot.</figcaption></figure>`;
}
function learn() {
  const categories = [...new Set(content.glossary.map(item => item.category))];
  return pageHead('Learn', 'Read the numbers.<br><span class="gradient-text">Keep the context.</span>', 'Plain-English guidance to help you explain what the report shows, what it does not, and who should see it.') + `
  <nav class="container jump-nav" aria-label="Learning topics"><a href="#reading">Read the report</a><a href="#privacy">Privacy and access</a><a href="#history">License history</a><a href="#glossary">Metric glossary</a></nav>
  <section class="section container" ${searchAttr('reading', 'How to read the report')}><div class="editorial-list"><article><span>${icon('people')}</span><div><h2>People, prompts and sessions are different.</h2><p>One person can send several prompts in a conversation and return to it later. The same person can also use chat and agents. Adding daily counts or experience groups can count that person more than once.</p></div></article><article><span>${icon('clock')}</span><div><h2>Habit summaries focus on one completed month.</h2><p>Look at the month named on the habit page. If your selected dates end in October, the habit summary describes September. Other activity tables may cover your entire selected date range, so their totals will not necessarily match that one-month summary.</p></div></article><article><span>${icon('chart')}</span><div><h2>Activity starts a conversation. It does not give a verdict.</h2><p>More sessions could mean useful work, retries or a difficult task. Scores and inferred use cases do not measure employee performance, answer quality or actual time saved.</p></div></article></div></section>
  <section class="section section-tinted" ${searchAttr('privacy', 'Minimum Group Size and row-level security')}><div class="container"><div class="section-heading">${eyebrow('Share responsibly')}<h2>What you display.<br>Who can see it.</h2><p>Minimum Group Size and row-level security do different jobs. Set up both.</p></div><div class="two-columns"><article class="panel"><h3>Minimum Group Size</h3><div class="thresholds"><div><strong>3</strong><span>Default<br>team-level reporting</span></div><div><strong>1</strong><span>Individual activity<br>when your policies permit</span></div></div><p>The threshold counts eligible people in the selected group, including those with no activity. A team of 20 with two active users can show aggregate results at the default setting; a team of two cannot.</p><p>${policy}</p><p>This is a display rule, not anonymization. Govern access to the underlying data, exports and Power BI model permissions separately.</p><details><summary>How to change the setting</summary><p>At first template load, enter Minimum Group Size before selecting Load. Later, use Home &gt; Transform data &gt; Manage parameters &gt; Minimum Group Size. Apply changes and clear old filters.</p><img src="assets/screenshots/minimum-group-size-first-load.png" alt="Initial template dialog with Minimum Group Size set to 3" loading="lazy"></details></article>
  <article class="panel"><h3>Row-level security (RLS)</h3><p>These are the <strong>two named security roles</strong> included in the Power BI model, not titles or job descriptions. Your report owner adds people or security groups to them.</p><div class="role-definition"><span class="tiny-label">Power BI role name</span><h4><code>Reporting hierarchy</code></h4><p>Viewers see themselves and their valid direct and indirect reports. If a viewer's sign-in does not match the directory, this role gives them no data.</p></div><div class="role-definition"><span class="tiny-label">Power BI role name</span><h4><code>All data viewers</code></h4><p>Members can see the whole dataset. Use this role only where full access is appropriate under your policies. Adding the same person to Reporting hierarchy does not restrict that full access.</p></div><p>In Power BI Service, open the semantic model &gt; Security, assign members, and Save. Share as Viewer or app consumer and test real viewer accounts. Workspace administrators and contributors are not restricted in the same way.</p></article></div>${note('Protect the source too.', 'Report roles do not protect CSV files, notebooks, SQL or Fabric OneLake access. Give each source and refresh account only the access it needs.', 'privacy')}</div></section>
  <section class="section container" ${searchAttr('history', 'What license history can and cannot tell you')}><div class="two-columns align-center"><div>${eyebrow('Understand license history')}<h2>When we saw a license.<br>Not when it was assigned.</h2><p>If collection records someone without a license on Monday and with a license on Friday, we know their recorded status changed. We do not know exactly when it changed between those collections.</p><p>When history is retained, the report can use those recorded states to group activity. The person still counts once in the overall total, but may appear in both paid and free groups during the selected period. Do not add those groups to find the total number of people.</p><p>Without recorded history, you see the supplied snapshot. Missing license information stays <strong>Unknown</strong>; it is not treated as "unlicensed." Organization and reporting relationships use the latest person information supplied.</p></div>${historyIllustration()}</div></section>
  <section class="section section-tinted" ${searchAttr('glossary', 'Plain-English metric glossary')}><div class="container"><div class="section-heading horizontal"><div>${eyebrow('Find the meaning')}<h2>A glossary you can scan.</h2><p>Choose a topic or search for a word. Open only the definitions you need.</p></div><label class="search-field">${icon('search')}<input type="search" id="glossary-search" placeholder="Search a metric or question" aria-label="Search metric glossary"></label></div><div class="glossary-browser"><nav class="topic-nav" aria-label="Glossary topics"><button class="active" data-glossary-category="All" aria-pressed="true">All topics</button>${categories.map(c => `<button data-glossary-category="${e(c)}" aria-pressed="false">${e(c)}</button>`).join('')}</nav><div><p class="result-count" id="glossary-count">${content.glossary.length} definitions</p><div id="glossary-list">${categories.map(category => `<section class="glossary-group" data-glossary-group="${e(category)}"><h3>${e(category)}</h3>${content.glossary.filter(i => i.category === category).map(item => `<details class="glossary-item" id="term-${slug(item.term)}" data-category="${e(item.category)}" data-search="${e(`${item.term} ${item.definition} ${item.category} ${item.aliases || ''}`.toLowerCase())}"><summary>${e(item.term)}</summary><p>${e(item.definition)}</p></details>`).join('')}</section>`).join('')}</div><p class="empty-state" id="glossary-empty" hidden>No matching definition. Try a shorter word, or <a href="help.html">visit Help</a>.</p></div></div></div></section>
  <section class="section container"><div class="soft-cta"><div><h2>Prefer a guide you can keep?</h2><p>Read the interpretation guide or use the storyboard for a leadership conversation.</p></div><div class="button-row">${dl('interpretation')}${dl('storyboard')}</div></div></section>`;
}

const downloadGroups = [
  ['sample-data', 'Try fictional sample data', 'Use all three files with the Local CSV template. Extract the activity CSV from its ZIP first.'],
  ['guides', 'Guides and presentations', 'Read, explain and share the report with confidence.'],
  ['fabric-onelake-notebooks', 'Fabric OneLake notebooks', 'For the Fabric OneLake notebook route, not the separate Fabric OneLake PAX route.'],
  ['advanced', 'Advanced data preparation', 'An optional specialist tool. Most users should start with PAX Cookbook Mini-Kitchen instead.']
];
function downloads() {
  return pageHead('Downloads', 'Your next step.<br><span class="gradient-text">The files to get there.</span>', 'Templates, sample data and practical guides, organized around what you want to do.') + `
  <nav class="container jump-nav" aria-label="Download topics"><a href="#templates">Report templates</a>${downloadGroups.map(([id, title]) => `<a href="#${id}">${e(title)}</a>`).join('')}<a href="#pax">PAX tools</a></nav>
  <section class="section container" ${searchAttr('templates', 'Download report templates')}><div class="section-heading"><h2>Start with your data connection.</h2><p>Download a template and open it in Power BI Desktop. The report experience is the same; the source connection is different.</p></div><div class="template-list">${release.templates.map(t => `<article class="template-row" id="${e(t.id)}"><div class="template-symbol">${icon(t.id.includes('fabric') ? 'layers' : t.id === 'sharepoint' ? 'book' : 'chart')}</div><div class="template-description"><h3>${e(t.title)}</h3><p>${e(t.subtitle)}</p><p class="muted">${e(t.bestFor)}</p><details><summary>Data and refresh details</summary><p>${e(t.source)}</p><p>${e(t.refresh)}</p><p>${e(t.note)}</p></details></div><div class="template-actions">${t.status === 'available' ? button('Download template', t.href, 'primary', 'download') : '<span class="availability-label">Coming soon</span>'}<a href="get-started.html#${e(t.id)}">Setup instructions</a><span class="file-meta">Power BI template &middot; v${e(release.version)}</span></div></article>`).join('')}</div></section>
  <section class="section section-tinted" ${searchAttr('resources', 'Guides, sample data and notebook downloads')}><div class="container"><div class="section-heading horizontal"><div>${eyebrow('Resources by topic')}<h2>Find what you need.</h2></div><label class="search-field">${icon('search')}<input type="search" id="download-search" placeholder="Find a guide, sample or notebook" aria-label="Search downloads"></label></div>${downloadGroups.map(([id, title, text]) => `<section class="download-topic" id="${id}" data-download-group><div class="topic-heading"><h3>${e(title)}</h3><p>${e(text)}</p></div><div class="resource-list">${release.downloads.filter(item => item.group === title).map(item => `<article class="resource-row" id="download-${e(item.id)}" data-search="${e(`${item.title} ${item.description} ${item.kind} ${item.group}`.toLowerCase())}"><span class="file-type">${e(item.kind)}</span><div><h4>${e(item.title)}</h4><p>${e(item.description)}</p></div><a class="icon-button" href="${e(item.href)}" aria-label="Download ${e(item.title)}">${icon('download')}</a></article>`).join('')}</div></section>`).join('')}<p class="empty-state" id="downloads-empty" hidden>No matching download. Try "sample", "guide" or "notebook".</p></div></section>
  <section class="section container" ${searchAttr('pax', 'Get PAX through Cookbook Mini-Kitchen')}>${kitchenPanel()}</section>`;
}

function help() {
  const shortcuts = [
    ['The report is blank', `#help-${slug('Why can a viewer open the report but see no data?')}`],
    ['I need data from IT', 'setup-reference.html#it-request'],
    ['Refresh needs attention', '#topic-refresh']
  ];
  return pageHead('Help', 'Find the right answer.<br><span class="gradient-text">Get back to your work.</span>', 'Choose a topic or search all the answers. Practical guidance for setup, missing data, privacy and refresh.') + `
  <section class="container help-entry"><label class="search-field search-large">${icon('search')}<input id="help-search" type="search" placeholder="Search all help, for example blank report or missing names" aria-label="Search all help topics"></label><div class="help-shortcuts"><span>Common starting points</span>${shortcuts.map(([title, href]) => `<a href="${href}">${title}${icon('arrow')}</a>`).join('')}</div></section>
  <section class="section container help-browser" ${searchAttr('answers', 'Browse help by topic')}><nav class="help-topic-nav" aria-label="Help topics"><p class="eyebrow">Choose a topic</p>${helpTopics.map((topic, i) => `<button data-help-category="${topic.category}" aria-pressed="${i === 0}" class="${i === 0 ? 'active' : ''}" aria-controls="help-results">${icon(topic.icon)}<span>${e(topic.title)}</span><small>${content.faqs.filter(item => item.category === topic.category).length}</small></button>`).join('')}<button data-help-category="All" aria-pressed="false" aria-controls="help-results">${icon('search')}<span>All topics</span><small>${content.faqs.length}</small></button><a class="text-link" href="setup-reference.html">IT setup &amp; permissions ${icon('arrow')}</a></nav>
  <div id="help-results"><p id="help-results-status" class="result-count" aria-live="polite"></p>${helpTopics.map(topic => `<section class="help-topic-panel" id="topic-${topic.category.toLowerCase()}" data-help-topic="${topic.category}"><div class="help-topic-heading">${icon(topic.icon)}<div><h2>${e(topic.title)}</h2><p>${e(topic.description)}</p></div></div><div class="faq-list">${content.faqs.filter(item => item.category === topic.category).map(item => `<details class="faq" id="help-${slug(item.q)}" data-category="${e(item.category)}" data-search="${e(`${item.q} ${item.a} ${topic.title}`.toLowerCase())}"><summary>${e(item.q)}</summary><div><p>${e(item.a)}</p>${item.category === 'Setup' ? '<a class="text-link" href="get-started.html">Open the simple setup guide</a>' : item.category === 'Refresh' ? '<a class="text-link" href="setup-reference.html#recurring">First collection and ongoing updates</a>' : ''}</div></details>`).join('')}</div></section>`).join('')}<p class="empty-state" id="help-empty" hidden>No matching answer. Try a shorter phrase or contact the team below.</p></div></section>
  <section class="section section-tinted" ${searchAttr('contact', 'Contact the team or request IT help')}><div class="container support-strip"><div>${eyebrow('A person can help too')}<h2>Still stuck?</h2><p>Tell the ${team} which connection you use, what you were trying to do and the error message. Remove names, tenant details and other private information.</p><div class="button-row">${button('Email the team', teamEmail, 'secondary')}${external('Report a product issue', 'https://github.com/microsoft/AI-in-One-Dashboard/issues/new/choose')}</div></div><div><h3>Need help from your IT team?</h3><p>Use a practical request for the data export, or share the permissions guide with whoever manages collection.</p><a class="text-link" href="setup-reference.html#it-request">Copy the data-export request ${icon('arrow')}</a><a class="text-link" href="setup-reference.html#permissions">IT setup &amp; permissions ${icon('arrow')}</a></div></div></section>
  <section class="section container">${note('Report security concerns privately.', 'Do not post vulnerabilities or sensitive logs in a public issue. Follow <a href="https://aka.ms/SECURITY.md" target="_blank" rel="noopener noreferrer">Microsoft security reporting guidance</a>.', 'privacy')}</section>`;
}
function privacy() {
  return pageHead('Privacy', 'A public guide.<br><span class="gradient-text">Not a data collection service.</span>', 'This website helps you understand and set up AI-in-One. It does not connect to your Microsoft 365 tenant or process your report data.') + `
  <section class="container prose" ${searchAttr('website-privacy', 'Website privacy and external resources')}><h2>What this site does</h2><p>Pages, screenshots and download links are publicly hosted. Screenshots use fictional data. Search runs in your browser. We do not request file uploads, tenant credentials or Microsoft 365 sign-in.</p><h2>Browser storage</h2><p>The site can remember your light or dark theme on your device. No analytics, session replay, advertising trackers or tracking cookies are added by this site. Do not put credentials, tenant data or private file paths in URLs.</p><h2>Hosting, downloads and videos</h2><p>GitHub Pages hosts the website and may process ordinary request metadata under its policies. Downloads come from GitHub-hosted project files. External sites have their own privacy policies.</p><p>The YouTube setup video is not loaded until you select Play; it then uses YouTube's privacy-enhanced embed. The report overview video is hosted by GitHub and loads when played. Video providers may process network information when you play their content.</p><h2>Your report and source data</h2><p>Data collection and reporting happen in your environment using PAX, Fabric OneLake and Power BI. They have their own permissions, logs and storage. Microsoft does not receive access to the data you load simply because you use this template.</p><p>Minimum Group Size controls display detail; it does not anonymize the data. Report security roles do not protect direct access to source files or tables.</p><h2>Responsible use</h2><p>Your organization is responsible for lawful collection, employee-reporting policies, privacy, access, retention, export and sharing. Audit telemetry should not be the only source used for licensing decisions or complete usage reporting. Compare it with the Microsoft 365 admin center and Viva Insights where appropriate.</p><p>The report does not measure employee performance, actual time saved, response quality or business outcomes. AI-in-One is currently available in English.</p><h2>Related policies</h2><p>${external('Microsoft Privacy Statement', 'https://privacy.microsoft.com/privacystatement')} &middot; ${external('GitHub Privacy Statement', 'https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement')}</p><p>AI-in-One is free and open source under the MIT license. Software and documentation are provided as-is, without warranty.</p></section>`;
}
function whatsNew() {
  return pageHead('What is new in v2.0', 'A clearer view.<br><span class="gradient-text">A better next question.</span>', 'A connected way to explore adoption, understand agents and share the right level of detail.') + `
  <section class="container feature-story" ${searchAttr('new-explorer', 'What is new: a connected Explorer')}><div class="feature-story-copy">${eyebrow('Start with your organization')}<h2>Your question sets the direction.</h2><p class="lead">Copilot Usage Explorer brings people, prompts, sessions and agents into one starting view. Choose a manager or department, set your dates and carry those selections through the report.</p><a class="text-link" href="explore.html?page=explorer">See Explorer in the report tour ${icon('arrow')}</a></div><button class="screenshot-button" data-zoom="assets/screenshots/01-copilot-usage-explorer.png" data-title="Copilot Usage Explorer" aria-label="Enlarge Explorer screenshot"><img src="assets/screenshots/01-copilot-usage-explorer.png" alt="Copilot Usage Explorer with fictional data" width="1280" height="792"><span>${icon('search')}Take a closer look</span></button></section>
  <section class="section section-tinted" ${searchAttr('new-agents', 'What is new: agent context and comparisons')}><div class="container feature-story reverse"><img class="feature-image" src="assets/screenshots/10-agent-details.png" alt="Agent Details report with fictional data" width="1280" height="792" loading="lazy"><div class="feature-story-copy">${eyebrow('Get to know your agents')}<h2>More context.<br>Less guesswork.</h2><p>Understand an agent's audience, repeat use, catalog information and creator or developer details. Clear review signals help you decide what to discuss with its owner.</p><div class="feature-notes"><div><h3>Compare like with like</h3><p>Read prompts beside sessions, see the month used for habit summaries and compare paid and free activity in context.</p></div><div><h3>Keep people in context</h3><p>Team-level reporting is the default. Recorded license history adds context without pretending to know exact assignment dates.</p></div></div><a class="text-link" href="explore.html?page=agent-details">Explore Agent Details ${icon('arrow')}</a></div></div></section>
  <section class="section container" ${searchAttr('overview-video', 'What is new video overview')}><div class="section-heading horizontal"><div>${eyebrow('Watch the report overview')}<h2>See the experience.</h2></div><div class="section-aside"><p>Watch the captioned introduction or keep a written overview.</p>${dl('whats-new', 'Download the what is new overview PDF')}</div></div>${overviewVideo()}</section>
  <section class="section section-tinted" ${searchAttr('setup-walkthrough', 'Setup walkthrough video')}><div class="container two-columns align-center"><div>${eyebrow('Ready to make it yours?')}<h2>Watch the setup.<br>Follow the guide.</h2><p class="lead">Choose Fabric OneLake, SharePoint or Local CSV. Use Mini-Kitchen for the PAX part and our setup guide for the report.</p><div class="button-row">${button('Get started', 'get-started.html')}</div></div><div>${setupVideo()}</div></div></section>`;
}

function reference() {
  const paxPermissions = [
    ['Copilot and agent activity', 'AuditLogsQuery.Read.All'],
    ['People, departments and licensing', 'User.Read.All and Organization.Read.All'],
    ['Agent 365 catalog, when collected', 'CopilotPackages.Read.All and Application.Read.All'],
    ['Security-group filtering, when used', 'GroupMember.Read.All']
  ];
  const permissionsTable = () => `<div class="table-wrap"><table><thead><tr><th>Collecting</th><th>Microsoft Graph permission</th></tr></thead><tbody>${paxPermissions.map(([purpose, permission]) => `<tr><td>${purpose}</td><td><code>${permission}</code></td></tr>`).join('')}</tbody></table></div>`;
  return pageHead('IT setup & permissions', 'Get the right access.<br><span class="gradient-text">Make setup simpler.</span>', 'A practical reference for the person who configures collection, source connections and scheduled refresh. Start with the sign-in method you will use.') + `
  <nav class="container jump-nav" aria-label="IT setup topics"><a href="#administrator">Prerequisites</a><a href="#permissions">Permissions by sign-in method</a><a href="#it-request">Request a data export</a><a href="#recurring">Ongoing updates</a><a href="#sharepoint-setup">SharePoint</a><a href="#local-setup">Local CSV</a><a href="#fabric-notebooks">Fabric OneLake: notebooks</a><a href="#fabric-pax">Fabric OneLake: PAX</a></nav>
  <section class="section container prose" ${searchAttr('administrator', 'Administrator prerequisites')}><h2>Before collection</h2><p>The person requesting the report should explain what they want to understand and who will use it. IT helps with access, collection and the technical setup.</p><ul><li>Install current Power BI Desktop. Confirm the Power BI licenses or capacity needed for sharing.</li><li>For PAX, install PowerShell 7 or later and Python 3.10 or later. Mini-Kitchen provides the PAX download and the commands for both the first collection and ongoing updates.</li><li>Check ${external('Purview audit logging', 'https://purview.microsoft.com/audit/auditsearch')} and the history available under the tenant's retention policy. Newly enabled logging does not recover earlier activity.</li><li>Choose a secure destination and give the collection account write access and the Power BI refresh account read access.</li><li>For Fabric OneLake, confirm capacity, Lakehouse access and a readable SQL analytics endpoint.</li></ul></section>
  <section class="section container prose" ${searchAttr('permissions', 'Application and delegated collection permissions')}><h2>Choose the permission model, not just the app registration.</h2><p>Microsoft Entra app registrations can have <strong>Delegated</strong> permissions or <strong>Application</strong> permissions. These are different access models. A certificate or secret is a credential, not a permission model.</p><div class="permission-comparison"><div><span class="tiny-label">Delegated permissions</span><h3>A person signs in</h3><p>The app acts on that person's behalf. Both the delegated permission and the signed-in person's access matter.</p></div><div><span class="tiny-label">Application permissions</span><h3>The app signs in on its own</h3><p>Permissions belong to the app or managed identity. An administrator grants consent before an unattended run.</p></div></div><p>For PAX, the <code>AppRegistration</code> sign-in option is app-only. Browser and device sign-in use a delegated user context. Do not add delegated permissions and expect them to authorize an app-only run, or vice versa.</p>
  <details class="route-detail" name="collection-permissions" id="delegated-permissions"><summary>PAX with a signed-in person: Delegated permissions</summary><div><p>In the app registration used for user sign-in, choose <strong>Microsoft Graph &gt; Delegated permissions</strong>. PAX requests the scopes for the features you collect; your tenant's consent policy determines who can consent.</p>${permissionsTable()}<p><strong>SharePoint:</strong> interactive PAX requests delegated <code>Sites.ReadWrite.All</code>. The signed-in person must already be able to edit the destination site and library. This does not grant them access to every site.</p><p><strong>Agent 365:</strong> delegated catalog collection also requires the signed-in person's appropriate directory role, such as AI Administrator or Global Administrator, and tenant eligibility for Agent 365.</p><p>Use Mini-Kitchen to choose the interactive sign-in method. Registering an app alone does not grant the user the necessary tenant roles or source access.</p></div></details>
  <details class="route-detail" name="collection-permissions" id="application-permissions"><summary>PAX without a user sign-in: Application permissions</summary><div><p>For app-only collection, choose <strong>Microsoft Graph &gt; Application permissions</strong> on the app registration and grant administrator consent. Managed identities need the equivalent application permissions on their service principal.</p>${permissionsTable()}<p><strong>SharePoint:</strong> grant <code>Sites.Selected</code>, then separately grant the app or managed identity write access to each intended destination site. Sites.Selected alone gives access to no sites.</p><p><strong>Agent 365:</strong> the application permissions belong to the app or managed identity, rather than a signed-in administrator. Tenant eligibility still applies.</p><p>Use Mini-Kitchen to configure the app-only sign-in and commands. Protect credentials using your organization's secret-management practices; do not send them in the IT request or paste them into public pages.</p></div></details>
  <details class="route-detail" name="collection-permissions" id="notebook-permissions"><summary>Fabric OneLake notebooks: Application permissions</summary><div><p>The collector application needs Microsoft Graph <strong>Application</strong> permissions with administrator consent: <code>AuditLogsQuery.Read.All</code>, <code>User.Read.All</code> and <code>Reports.Read.All</code>. This differs from PAX's collection permission set.</p><p>The notebook execution account needs Lakehouse table-write access and permission to retrieve the designated client secret from Azure Key Vault. Preparation needs notebook execution and Lakehouse access; reading a processed PAX CSV pair directly does not require the Graph collectors.</p><a class="text-link" href="#fabric-notebooks">Continue to the Fabric OneLake notebook instructions ${icon('arrow')}</a></div></details>
  ${note('Collection access is not report access.', 'Power BI refresh needs its own source read access. Viewers need report access and the appropriate model security role. These do not replace one another.')}</section>
  <section class="section container prose" ${searchAttr('it-request', 'Request a PAX data export from IT')}><h2>Ask IT for the export you need.</h2><p>Send a practical request covering what the report is, which data to collect, the required permissions and where to get PAX. Add your preferred dates and destination before sending it.</p><div class="button-row"><button class="button button-primary" data-copy="${e(itRequest)}">Copy the data-export request</button><a class="button button-secondary" href="mailto:?subject=${encodeURIComponent('Request: data export for AI-in-One (Power BI)')}&amp;body=${encodeURIComponent(itRequest)}">Open an email draft</a></div><details class="route-detail"><summary>Read the full request before copying</summary><pre class="request-text"><code>${e(itRequest)}</code></pre></details></section>
  <section class="section container prose" ${searchAttr('recurring', 'First PAX collection and ongoing updates')}><h2>Use Mini-Kitchen from the first collection onward.</h2><p>Mini-Kitchen creates commands for <strong>both your first collection and later updates</strong>. It also links to the PAX script download. It does not run the commands or connect to your tenant.</p><ol><li><strong>Start with the history you need.</strong> In Mini-Kitchen, choose AI-in-One, your dates, storage destination and sign-in method. Download PAX there and run the generated command.</li><li><strong>Keep the matching results together.</strong> PAX prepares the people, activity and optional agent catalog for the report. Record their locations so Power BI can use them.</li><li><strong>Add new days to those same results.</strong> Return to Mini-Kitchen for an update command. Point it at the existing outputs so the report keeps the same connections.</li><li><strong>Schedule if needed.</strong> IT can schedule the generated update command with the right sign-in method. Mini-Kitchen creates the command; the schedule runs it.</li><li><strong>Refresh Power BI afterward.</strong> Wait for a successful, complete data update and any cloud synchronization before the report refresh begins.</li></ol><details class="route-detail"><summary>Administrator detail: dates, watermarks and license history</summary><p>The initial PAX collection uses <code>-StartDate</code> and an exclusive <code>-EndDate</code>. Watermark updates use <code>-Watermark</code> and the exact existing outputs through append parameters. The first watermark also uses <code>-WatermarkStartDate</code> for the first day not yet collected; later updates omit it and omit StartDate/EndDate. Dates cover complete UTC days.</p><p>When your collection process uses <code>-UserHistory On</code>, it can retain license states observed going forward. It does not recover changes that were never collected. Use matching Users and Interactions from the same collection history.</p><p>Mini-Kitchen explains the switches and creates the commands for each stage.</p></details></section>
  <section class="section container prose" ${searchAttr('sharepoint-setup', 'Detailed SharePoint connection setup')}><h2>SharePoint: connect the matching CSV files.</h2><ol><li>Use Mini-Kitchen to create the AI-in-One collection command with a SharePoint destination. Set up <a href="#permissions">delegated or application permissions</a> for the sign-in method you choose.</li><li>Let PAX finish writing the matching processed Interactions and Users CSV files. Include the optional Agent 365 catalog if you want its metadata.</li><li>For each CSV, open its SharePoint library, select the file, open <strong>Details</strong> and copy <strong>Path</strong>. Use the direct HTTPS CSV path, not a sharing link or the browser address bar.</li><li>Open the SharePoint template in Power BI Desktop. Paste the Interactions path into <strong>Copilot Interactions File</strong>, the Users path into <strong>Org Data File</strong>, and the optional catalog path into <strong>Agent 365</strong>. Keep <strong>Minimum Group Size at 3</strong> unless your policies permit another setting.</li><li>Select Load and sign in with the organizational account that can read the files.</li><li>In Power BI Service, configure organizational OAuth2 credentials for each source and test Refresh now. Schedule refresh after PAX has successfully finished; a gateway is normally unnecessary.</li></ol><p>Raw audit exports are not substitutes for processed CSVs. The account collecting data needs write access; the account refreshing the report needs read access. Continue to <a href="get-started.html#share">report security and sharing</a> before giving viewers access.</p>${dl('interpretation', 'Download the interpretation guide')}</section>
  <section class="section container prose" ${searchAttr('local-setup', 'Detailed Local CSV connection setup')}><h2>Local CSV: connect files on a PC or network.</h2><ol><li>Use Mini-Kitchen for the first AI-in-One collection and later updates, choosing a local output folder. For a fictional trial, <a href="get-started.html#sample">use the sample data instead</a>; PAX is not needed.</li><li>Keep the matching processed Users and Interactions CSV files together. For the sample, extract the Interactions CSV from the ZIP first.</li><li>In File Explorer, use <strong>Copy as path</strong>. Remove the surrounding quotation marks before pasting into Power BI.</li><li>Open the Local CSV template in Power BI Desktop. Set <strong>Copilot Interactions File</strong> to the activity CSV and <strong>Org Data File</strong> to the Users CSV. Set <strong>Agent 365</strong> to the catalog CSV if you have one; otherwise leave it blank.</li><li>Keep <strong>Minimum Group Size at 3</strong> for team-level reporting and select Load.</li><li>Refresh directly in Desktop. For scheduled Service refresh, install and configure an on-premises data gateway that can read those same paths. Otherwise, refresh in Desktop and republish.</li></ol><p>For shared reporting, continue to <a href="get-started.html#share">viewer access and sharing</a>. Source-file access and report-viewer access are separate.</p></section>
  <section class="section container prose" ${searchAttr('fabric-notebooks', 'Detailed Fabric OneLake notebook setup')}><h2>Fabric OneLake: notebook collection</h2><p>This route uses three collector notebooks and a preparation notebook, all attached to the same default Lakehouse. The collectors call Microsoft Graph; <strong>Power BI refresh does not</strong>. The report imports prepared tables through the SQL analytics endpoint.</p><ol><li>Give the collector application the required audit, directory and reporting permissions. Store its client secret in Azure Key Vault and give the notebook execution account permission to retrieve it.</li><li>Import the four notebooks and attach the same Lakehouse. Configure tenant/client identifiers and Key Vault references; never paste secret values into cells.</li><li>Run the audit, organization and licensing collectors, then preparation. The pipeline can coordinate this order.</li><li>Preparation checks input age, tenant, identities, keys and output consistency. It publishes <code>aio_v2_users</code>, <code>aio_v2_interactions</code> and <code>aio_v2_publication</code>.</li><li>Wait for SQL to show the completed tables with a matching <strong>Ready</strong> publication. A Ready marker in the Lakehouse alone does not prove SQL synchronization.</li><li>Configure the Power BI SQL cloud connection, plus separate SharePoint credentials if the optional catalog is used. Keep updates and Power BI Import refresh non-overlapping.</li></ol><p>Blank manager references can be intentional top-of-chain records. Missing requested managers and cycles need careful source review; do not invent reporting relationships to grant access.</p><details><summary>Alternative: prepare an existing pair of PAX CSV files</summary><p>The preparation notebook can accept both processed Users and Interactions CSV paths in Lakehouse Files. Supply a matching pair, not raw audit exports. Run preparation directly for this option; the supplied pipeline still runs its Graph collectors. This still produces the Fabric OneLake notebook edition's prepared tables, not the direct Fabric OneLake PAX connection.</p></details><div class="button-row">${dl('fabric-guide')}${button('Get the notebooks', 'downloads.html#fabric-onelake-notebooks', 'secondary', 'download')}</div></section>
  <section class="section container prose" ${searchAttr('fabric-pax', 'Detailed Fabric OneLake PAX setup')}><h2>Fabric OneLake: PAX collection</h2><p>This separate connection reads PAX-prepared <code>AIO_Users</code> and <code>AIO_CopilotInteractions</code> tables and optionally <code>Agent365</code>. It does not run the notebook collectors or preparation.</p><ol><li>Let the entire PAX data update finish successfully and wait for SQL synchronization.</li><li>Enter the SQL endpoint, Lakehouse database, physical schema and optional catalog setting. Use the existing parameters, not a OneLake file URL.</li><li>The template checks required columns, data types, unique Users state keys and activity-to-Users relationships. These checks do not prove every table comes from one completed update.</li><li>Schedule the SQL Import refresh after your normal PAX completion and SQL synchronization window. Exclude all table writers for the entire refresh.</li></ol>${note('Download coming soon.', 'This connection is documented here, but its template is not yet a public download. The Fabric OneLake notebook template cannot replace it.')}<div class="button-row">${external('Open Mini-Kitchen', release.pax.href, 'button button-primary')}${external('PAX v2.0 repository', release.pax.repository)}</div></section>
  <section class="section container prose" ${searchAttr('refresh', 'Power BI credentials and scheduled refresh')}><h2>Configure Power BI refresh</h2><p><strong>SharePoint:</strong> set organizational OAuth2 credentials with read access to each file. A gateway is normally unnecessary.</p><p><strong>Local or network CSV:</strong> configure an on-premises data gateway that can read the same paths, or refresh in Desktop and republish.</p><p><strong>Fabric OneLake:</strong> use a SQL cloud connection for the refresh account. The report is Import, not Direct Lake. Private networking or tenant policies may add requirements.</p><p>Test Refresh now, then confirm a later scheduled run succeeds. Viewer security roles do not grant the refresh account source access, and source access does not grant report-viewer access.</p><div class="button-row">${button('Back to the simple setup guide', 'get-started.html', 'secondary')}${button('Troubleshoot a symptom', 'help.html', 'secondary')}</div></section>`;
}

const pages = [
  ['index.html', 'Overview', 'Understand Microsoft Copilot adoption and agent engagement in your organization.', home],
  ['get-started.html', 'Get started', 'Set up AI-in-One with a simple guide and PAX Cookbook Mini-Kitchen.', setup],
  ['explore.html', 'Explore', 'Find the report view that answers your question.', explore],
  ['learn.html', 'Learn', 'Understand metrics, privacy, security roles and license history.', learn],
  ['downloads.html', 'Downloads', 'Direct templates, sample data, guides and Fabric OneLake resources.', downloads],
  ['help.html', 'Help', 'Practical answers for setup, data, access and refresh.', help],
  ['privacy.html', 'Privacy', 'How this public guide and your reporting environment handle privacy.', privacy],
  ['whats-new.html', "What's New", 'See what is new in AI-in-One v2.0 and watch the walkthroughs.', whatsNew],
  ['setup-reference.html', 'IT setup & permissions', 'Administrator prerequisites, collection and refresh details.', reference]
];
const nav = [['index.html', 'Overview'], ['get-started.html', 'Get started'], ['explore.html', 'Explore'], ['learn.html', 'Learn'], ['downloads.html', 'Downloads'], ['whats-new.html', "What's New"], ['help.html', 'Help']];
const index = [];
for (const [file, title, description, render] of pages) {
  const body = linkReferences(render());
  index.push({ title, text: plain(body), summary: description, href: file, type: 'Page' });
  const sections = /<section\b([^>]*\bdata-search-title="[^"]+"[^>]*)>([\s\S]*?)<\/section>/g;
  for (const match of body.matchAll(sections)) {
    const id = match[1].match(/\bid="([^"]+)"/)?.[1];
    const heading = match[1].match(/\bdata-search-title="([^"]+)"/)?.[1];
    if (id && heading) index.push({ title: plain(heading), text: plain(match[2]), summary: plain(match[2]).slice(0, 180), href: `${file}#${id}`, type: 'Section' });
  }
  const html = `<!doctype html>
<html lang="en" data-page="${file.replace('.html', '')}"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><script src="assets/theme.js"></script>
<title>${e(title)} | AI-in-One v2.0</title><meta name="description" content="${e(description)}"><meta name="color-scheme" content="light dark"><meta property="og:title" content="${e(title)} | AI-in-One v2.0"><meta property="og:description" content="${e(description)}"><meta property="og:type" content="website">
<link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/styles.css"><script defer src="assets/content.js"></script><script defer src="assets/catalog.js"></script><script defer src="assets/search-index.js"></script><script defer src="assets/app.js"></script>
</head><body><a class="skip-link" href="#main">Skip to main content</a>
<header class="site-header"><div class="header-inner container"><a class="brand" href="index.html" aria-label="AI-in-One home">${brand}<span>AI-in-One<small>MICROSOFT COPILOT ANALYTICS</small></span></a><button class="icon-button menu-toggle" id="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="primary-nav">${icon('menu')}</button><nav id="primary-nav" class="primary-nav" aria-label="Primary">${nav.map(([href, label]) => `<a href="${href}" ${href === file ? 'aria-current="page"' : ''}>${label}</a>`).join('')}</nav><div class="header-actions">${external('Analytics Hub', 'https://aka.ms/Analytics-Hub', 'hub-button')}<button class="icon-button" id="site-search-toggle" aria-label="Search the whole site" aria-expanded="false" aria-controls="site-search-dialog">${icon('search')}</button><button class="icon-button" id="theme-toggle" aria-label="Switch color theme">${icon('sun')}</button></div></div></header>
<div class="preview-band"><div class="container"><span class="release-badge">${e(release.channel)}</span><span>AI-in-One v${e(release.version)}</span><a href="whats-new.html">See what is new ${icon('arrow')}</a></div></div>
<main id="main">${body}</main>
<footer class="site-footer"><div class="container footer-grid"><div><a class="brand" href="index.html">${brand}<span>AI-in-One</span></a><p>Understand adoption.<br>Ask better questions.<br>Make the next conversation count.</p><p>From the ${team}.</p></div><div><h2>Your next step</h2><a href="get-started.html">Set up the dashboard</a><a href="setup-reference.html">IT setup &amp; permissions</a><a href="explore.html">Explore the report</a><a href="downloads.html">Download resources</a>${external('PAX Cookbook Mini-Kitchen', release.pax.href)}</div><div><h2>Understand and share</h2><a href="learn.html#glossary">Metric glossary</a><a href="learn.html#privacy">Privacy and access</a><a href="whats-new.html">What's New in v2.0</a><a href="help.html">Get help</a></div><div><h2>More from the team</h2>${external('Analytics Hub', 'https://aka.ms/Analytics-Hub')}${external('AI-in-One source repository', 'https://github.com/microsoft/AI-in-One-Dashboard/tree/preview')}${external('PAX v2.0 repository', release.pax.repository)}<a href="privacy.html">Website privacy</a></div></div><div class="container footer-bottom"><span>&copy; Microsoft Corporation &middot; MIT licensed &middot; Provided as-is.</span><span>No tenant data is collected by this website.</span></div></footer>
<dialog id="site-search-dialog" class="search-dialog" aria-labelledby="site-search-title"><div class="search-dialog-header"><h2 id="site-search-title">Find your next step.</h2><button class="icon-button" id="close-search" aria-label="Close site search">&times;</button></div><label class="search-field search-large">${icon('search')}<input id="site-search-input" type="search" placeholder="Search templates, setup, metrics or help" aria-label="Search the entire site" autocomplete="off"></label><p class="search-hint" id="site-search-status" aria-live="polite">Search everything. Matching downloads appear first.</p><div id="site-search-results"></div></dialog>
<dialog id="image-dialog" class="image-dialog" aria-label="Enlarged report screenshot"><div class="dialog-toolbar"><strong id="dialog-title">Report screenshot</strong><button class="icon-button" id="close-dialog" aria-label="Close screenshot">&times;</button></div><img id="dialog-image" alt=""><p>Fictional example data. Not connected to your organization.</p></dialog><div id="live-status" class="sr-only" aria-live="polite"></div></body></html>`;
  fs.writeFileSync(path.join(root, file), html);
}
for (const item of [...release.templates.filter(t => t.status === 'available'), ...release.downloads]) {
  index.push({ title: item.title, text: [item.title, item.description, item.subtitle, item.source, item.group, item.kind, item.id].filter(Boolean).join(' '), summary: item.description || item.subtitle, href: item.href, type: 'Download', format: item.kind || 'Power BI template' });
}
for (const item of content.glossary) index.push({ title: item.term, text: `${item.term} ${item.definition} ${item.aliases}`, summary: item.definition, href: `learn.html#term-${slug(item.term)}`, type: 'Definition' });
for (const item of content.faqs) index.push({ title: item.q, text: `${item.q} ${item.a}`, summary: item.a, href: `help.html#help-${slug(item.q)}`, type: 'Help' });
for (const item of content.tour) index.push({ title: item.title, text: `${item.title} ${item.question} ${item.summary} ${item.bullets.join(' ')} ${item.tip} ${item.caution}`, summary: item.question, href: `explore.html?page=${item.id}`, type: 'Report view' });
fs.writeFileSync(path.join(root, 'assets', 'search-index.js'), `window.AIO_SEARCH = ${JSON.stringify(index).replace(/</g, '\\u003c')};\n`);
fs.writeFileSync(path.join(root, '404.html'), `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found | AI-in-One</title><script src="/AI-in-One-Dashboard/assets/theme.js"></script><link rel="icon" href="/AI-in-One-Dashboard/assets/favicon.svg"><link rel="stylesheet" href="/AI-in-One-Dashboard/assets/styles.css"></head><body><main class="page-head"><div class="container"><p class="eyebrow">A different path</p><h1>This page is not here.</h1><p class="lead">Let's get you back to the report.</p><div class="button-row"><a class="button button-primary" href="/AI-in-One-Dashboard/">Return to AI-in-One</a></div></div></main></body></html>`);
fs.writeFileSync(path.join(root, 'sitemap.xml'), `<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${pages.map(([file]) => `<url><loc>https://microsoft.github.io/AI-in-One-Dashboard/${file === 'index.html' ? '' : file}</loc></url>`).join('')}</urlset>`);
console.log(`Built ${pages.length} pages, 404, sitemap and ${index.length} searchable entries.`);
